def calculate_similarity(text_a, text_b):
    """计算两段中文文本的Jaccard相似度"""
    tokens_a = set(jieba.cut(text_a))
    tokens_b = set(jieba.cut(text_b))
    intersection = tokens_a & tokens_b
    union = tokens_a | tokens_b
    if not union:
        return 0.0
    return len(intersection) / len(union)

